// Cloudflare Agents SDK 0.31.0+의 핵심 구성 형태를 축약한 문서 기반 예시
// 실제 실행에는 Browser binding, Durable Object, 포트 연결 함수가 필요함
const browser = new Browser({
  provider: browserRun(env.BROWSER, {
    guardrails: { allowedDomains: [] },
    internalHosts: {
      router: ctx.exports.InternalHostRouter,
      hosts: {
        "preview.internal": {
          description: "Development preview",
          target: z.object({ port: z.number().int().min(1024) }),
          fetch: (request, { port }) => fetchSandboxPort(port, request),
        },
      },
    },
  }),
});
